svg.script:
// Tout demarre au chargement complet, apres animations-config.js (window.ANIM_CONFIG).
window.addEventListener('load', function () {
var CFG = window.ANIM_CONFIG || {};
// Valeur de reglage par chemin 'a.b.c', ou def si absente.
function cfg(path, def) {
  var v = CFG, parts = path.split('.');
  for (var i = 0; i < parts.length; i++) { if (v == null) return def; v = v[parts[i]]; }
  return v === undefined || v === null ? def : v;
}
// Duree en ms depuis un reglage en secondes : nombre fixe ou [min, max] tire au hasard.
function cfgMs(path, def) {
  var v = cfg(path, def);
  if (Array.isArray(v)) return (v[0] + Math.random() * (v[1] - v[0])) * 1000;
  return v * 1000;
}
var rootStyle = document.documentElement.style;
// ~1/3 des fenetres restent eteintes (decale au hasard a chaque chargement)
Array.prototype.forEach.call(document.querySelectorAll('.win-light'), function (e) { if (!e.querySelector('.lanterne') && Math.random() < cfg('lumieres.eteintes', 0.35)) e.style.display = 'none'; });
Array.prototype.forEach.call(document.querySelectorAll('.flame-glow.lanterne'), function (e) { e.parentNode.classList.add('exterieur'); var h = e.parentNode.querySelector('.lum-halo'); if (h) h.setAttribute('fill', 'url(#lum-lanterne)'); e.style.animationDelay = (-Math.random()).toFixed(2) + 's'; });
rootStyle.setProperty('--ble-balancement', cfg('ble.balancement', 3.4) + 's');
rootStyle.setProperty('--ble-rafale', cfg('ble.rafale', 11) + 's');
rootStyle.setProperty('--ble-force-balancement', cfg('ble.forceBalancement', 5));
rootStyle.setProperty('--ble-force-rafale', cfg('ble.forceRafale', 8));
rootStyle.setProperty('--arbre-force', cfg('ble.forceArbres', 0.35));
rootStyle.setProperty('--moulin-tour', cfg('moulin.tour', 16) + 's');
rootStyle.setProperty('--chat-queue', cfg('chat.queue', 3.7) + 's');
rootStyle.setProperty('--chat-respiration', cfg('chat.respiration', 2.9) + 's');
rootStyle.setProperty('--chat-tete', cfg('chat.tete', 11) + 's');
rootStyle.setProperty('--chat-oreille', cfg('chat.oreille', 7.3) + 's');
// Lumieres des fenetres : multiplicateur des durees/delais inline.
var lightK = cfg('lumieres.duree', 1);
if (lightK !== 1) {
  Array.prototype.forEach.call(document.querySelectorAll('.win-light'), function (e) {
    e.style.animationDuration = (parseFloat(e.style.animationDuration) * lightK) + 's';
    e.style.animationDelay = (parseFloat(e.style.animationDelay) * lightK) + 's';
  });
}

// Horloge virtuelle commune aux aiguilles de la tour et au cycle jour/nuit.
// mode 'reel' (par defaut) : suit l'heure de l'ordinateur.
// mode 'accelere' : une journee complete de 24h dure 'jourNuit.dureeCycle' minutes.
var tempsMode = cfg('jourNuit.mode', 'reel'), tempsCycleMin = cfg('jourNuit.dureeCycle', 20);
var temps_t0 = performance.now();
var temps_depart = new Date();
var temps_startHour = temps_depart.getHours() + temps_depart.getMinutes() / 60 + temps_depart.getSeconds() / 3600;
function heureVirtuelle() {
  if (tempsMode === 'accelere') return (temps_startHour + (performance.now() - temps_t0) / 60000 / tempsCycleMin * 24) % 24;
  var d = new Date(); return d.getHours() + d.getMinutes() / 60 + d.getSeconds() / 3600;
}

(function () {
  // Mouvement "a l'ancienne" : l'aiguille des secondes avance par a-coups
  // (un tic par seconde), comme une horloge mecanique a echappement,
  // plutot qu'un balayage continu de montre a quartz.
  var hourHand = document.getElementById('hand-hour');
  var minuteHand = document.getElementById('hand-minute');
  var secondHand = document.getElementById('hand-second');
  // En mode accelere, l'aiguille des secondes tournerait bien trop vite pour etre
  // lisible : on la masque et on ne s'occupe plus que des heures/minutes.
  if (tempsMode === 'accelere') secondHand.style.display = 'none';

  function update() {
    var h = heureVirtuelle();
    var totalSec = h * 3600;

    var minAngle = (totalSec % 3600) / 3600 * 360;
    var hourAngle = (h % 12) / 12 * 360;

    hourHand.setAttribute('transform', 'rotate(' + hourAngle + ')');
    minuteHand.setAttribute('transform', 'rotate(' + minAngle + ')');
    if (tempsMode !== 'accelere') {
      var secAngle = (totalSec % 60) / 60 * 360;
      secondHand.setAttribute('transform', 'rotate(' + secAngle + ')');
    }
  }

  update();
  setInterval(update, 1000);
})();

(function () {
  // Portes : ouvertures aleatoires (quand, quel battant, de combien, a quelle vitesse).
  // Chaque battant est redessine a chaque image : ses points (contour, hachures du bois,
  // traverses, heurtoir) sont tournes en 3D autour de la charniere puis projetes en
  // perspective (oeil au centre de la porte, a la distance eye.d). Les hachures suivent
  // donc le battant au lieu d'etre etirees comme une image.
  var NS = 'http://www.w3.org/2000/svg';
  var defs = document.querySelector('defs');
  var clipCount = 0;

  function rand(a, b) { return a + Math.random() * (b - a); }
  function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
  function el(tag, attrs, parent) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }
  function quad(p0, c, p1, n) {
    var out = [];
    for (var i = 1; i <= n; i++) {
      var t = i / n, a = (1 - t) * (1 - t), b = 2 * (1 - t) * t, d = t * t;
      out.push([a * p0[0] + b * c[0] + d * p1[0], a * p0[1] + b * c[1] + d * p1[1]]);
    }
    return out;
  }
  function r2(v) { return Math.round(v * 100) / 100; }

  // Rotation autour de l'axe vertical x = hinge, puis projection perspective.
  // Renvoie [x, y, facteur d'echelle].
  function project(c, ang, x, y) {
    var u = x - c.hinge;
    var X = c.hinge + u * Math.cos(ang);
    var Z = (c.outward ? 1 : -1) * Math.abs(u) * Math.sin(ang);
    var s = c.eye.d / (c.eye.d - Z);
    return [c.eye.x + (X - c.eye.x) * s, c.eye.y + (y - c.eye.y) * s, s];
  }
  function setLine(e, p, q) {
    e.setAttribute('x1', r2(p[0])); e.setAttribute('y1', r2(p[1]));
    e.setAttribute('x2', r2(q[0])); e.setAttribute('y2', r2(q[1]));
  }

  function makeLeaf(parent, c) {
    var leaf = { c: c, angle: -1, tl: null };
    var id = 'battant-clip-' + (clipCount++);
    leaf.clip = el('path', {}, el('clipPath', { id: id, clipPathUnits: 'userSpaceOnUse' }, defs));

    // Corps du battant : meme rendu que le motif hatchWood + sketchyHeavy du calque.
    var g = el('g', { filter: 'url(#sketchyHeavy)' }, parent);
    leaf.fill = el('path', { fill: '#6b4a2e' }, g);
    var hatch = el('g', { 'clip-path': 'url(#' + id + ')', stroke: '#2a1a0a' }, g);
    var xmin = Math.min(c.hinge, c.free), xmax = Math.max(c.hinge, c.free);
    leaf.hLines = []; leaf.vLines = [];
    for (var y = Math.floor(c.top / 8) * 8 + 4; y <= c.bottom; y += 8)
      leaf.hLines.push({ y: y, e: el('line', { 'stroke-width': 1.5, opacity: 0.7 }, hatch) });
    for (var x = Math.floor(xmin / 8) * 8 + 4; x <= xmax; x += 8)
      leaf.vLines.push({ x: x, e: el('line', { opacity: 0.5 }, hatch) });
    leaf.shade = el('path', { fill: '#000', opacity: 0 }, g);
    leaf.edge = el('path', { fill: 'none', stroke: '#1a0f05', 'stroke-width': c.stroke }, g);

    // Traverses et anneaux/heurtoir (sketchyMedium, comme dans le calque).
    var det = el('g', { filter: 'url(#sketchyMedium)', stroke: '#1a0f05' }, parent);
    leaf.planks = c.planks.map(function (p) {
      return { p: p, e: el('line', { 'stroke-width': 3 }, det) };
    });
    leaf.rings = c.rings.map(function (r) {
      return { r: r, e: el('ellipse', r.fill ? { fill: '#1a0f05', stroke: 'none' }
                                             : { fill: 'none', 'stroke-width': r.w }, det) };
    });
    return leaf;
  }

  function render(leaf, ang) {
    if (ang === leaf.angle) return;
    leaf.angle = ang;
    var c = leaf.c;
    var d = 'M ' + c.outline.map(function (p) {
      var q = project(c, ang, p[0], p[1]);
      return r2(q[0]) + ',' + r2(q[1]);
    }).join(' L ') + ' Z';
    leaf.fill.setAttribute('d', d);
    leaf.clip.setAttribute('d', d);
    leaf.shade.setAttribute('d', d);
    leaf.edge.setAttribute('d', d);
    // Le battant s'assombrit en tournant (il quitte la lumiere de la rue).
    leaf.shade.setAttribute('opacity', r2((c.outward ? 0.2 : 0.45) * Math.sin(ang)));

    leaf.hLines.forEach(function (h) {
      setLine(h.e, project(c, ang, c.hinge, h.y), project(c, ang, c.free, h.y));
    });
    var vw = r2(Math.max(0.35, Math.cos(ang)));
    leaf.vLines.forEach(function (v) {
      setLine(v.e, project(c, ang, v.x, c.top), project(c, ang, v.x, c.bottom));
      v.e.setAttribute('stroke-width', vw);
    });
    leaf.planks.forEach(function (pl) {
      setLine(pl.e, project(c, ang, pl.p[0], pl.p[1]), project(c, ang, pl.p[2], pl.p[3]));
    });
    leaf.rings.forEach(function (rg) {
      var q = project(c, ang, rg.r.x, rg.r.y);
      rg.e.setAttribute('cx', r2(q[0])); rg.e.setAttribute('cy', r2(q[1]));
      rg.e.setAttribute('rx', r2(Math.max(0.5, rg.r.r * Math.cos(ang) * q[2])));
      rg.e.setAttribute('ry', r2(rg.r.r * q[2]));
    });
  }

  // Angle courant d'un battant selon sa sequence ouverture / pause / fermeture.
  function angleAt(leaf, now) {
    var tl = leaf.tl;
    if (!tl) return 0;
    var t = now - tl.start;
    if (t < 0) return 0;
    if (t < tl.open) return tl.max * ease(t / tl.open);
    t -= tl.open;
    if (t < tl.hold) return tl.max;
    t -= tl.hold;
    if (t < tl.close) return tl.max * (1 - ease(t / tl.close));
    leaf.tl = null;
    return 0;
  }

  var doors = [];
  var running = false;
  function tick(now) {
    var active = false;
    doors.forEach(function (door) {
      var any = false;
      door.leaves.forEach(function (leaf) {
        render(leaf, angleAt(leaf, now));
        if (leaf.tl) any = true;
      });
      // Porte fermee : on masque l'overlay et c'est la porte du calque qui s'affiche.
      door.group.setAttribute('display', any ? 'inline' : 'none');
      if (any) active = true;
    });
    running = active;
    if (active) requestAnimationFrame(tick);
  }

  // amount : 0..1 (fraction de l'ouverture maxi c.maxDeg). Renvoie la duree totale (ms).
  function swing(leaf, amount, delay) {
    leaf.tl = {
      start: performance.now() + delay,
      max: amount * leaf.c.maxDeg * Math.PI / 180,
      open: cfgMs('portes.ouverture', [2.2, 4]), hold: cfgMs('portes.ouverte', [1.2, 4.5]),
      close: cfgMs('portes.fermeture', [2.2, 4.5])
    };
    if (!running) { running = true; requestAnimationFrame(tick); }
    return delay + leaf.tl.open + leaf.tl.hold + leaf.tl.close;
  }

  // --- Tour : double battant, s'ouvre vers l'interieur ---
  var tourGroup = document.getElementById('porte-tour');
  var tourEye = { x: 2520, y: 1505, d: 900 };
  var tourParent = tourGroup.querySelector('.battants');
  var tourG = makeLeaf(tourParent, {
    hinge: 2380, free: 2520, top: 1340, bottom: 1670, stroke: 6, maxDeg: 85, outward: false, eye: tourEye,
    outline: [[2380, 1670], [2380, 1420]]
      .concat(quad([2380, 1420], [2380, 1340], [2520, 1340], 10)).concat([[2520, 1670]]),
    planks: [[2400, 1400, 2500, 1400], [2400, 1500, 2500, 1500], [2400, 1600, 2500, 1600]],
    rings: [{ x: 2510, y: 1520, r: 8, w: 3 }]
  });
  var tourD = makeLeaf(tourParent, {
    hinge: 2660, free: 2520, top: 1340, bottom: 1670, stroke: 6, maxDeg: 85, outward: false, eye: tourEye,
    outline: [[2660, 1670], [2660, 1420]]
      .concat(quad([2660, 1420], [2660, 1340], [2520, 1340], 10)).concat([[2520, 1670]]),
    planks: [[2540, 1400, 2640, 1400], [2540, 1500, 2640, 1500], [2540, 1600, 2640, 1600]],
    rings: [{ x: 2530, y: 1520, r: 8, w: 3 }]
  });
  doors.push({ group: tourGroup, leaves: [tourG, tourD] });

  // --- Auberge : battant unique, charniere a droite, pousse depuis l'interieur (vers la rue) ---
  var aubGroup = document.getElementById('porte-auberge');
  var auberge = makeLeaf(aubGroup.querySelector('.battants'), {
    hinge: 1300, free: 1200, top: 1570, bottom: 1750, stroke: 5, maxDeg: 70, outward: true,
    eye: { x: 1250, y: 1660, d: 450 },
    outline: [[1200, 1750], [1200, 1600]]
      .concat(quad([1200, 1600], [1200, 1570], [1250, 1570], 6))
      .concat(quad([1250, 1570], [1300, 1570], [1300, 1600], 6)).concat([[1300, 1750]]),
    planks: [],
    rings: [{ x: 1220, y: 1660, r: 6, w: 2.5 }, { x: 1220, y: 1660, r: 3, fill: true }]
  });
  doors.push({ group: aubGroup, leaves: [auberge] });

  // --- Guilde : double battant, s'ouvre vers l'interieur (comme la tour) ---
  var guildeGroup = document.getElementById('porte-guilde');
  var guildeEye = { x: 190, y: 390, d: 400 };
  var guildeParent = guildeGroup.querySelector('.battants');
  var guildeG = makeLeaf(guildeParent, {
    hinge: 130, free: 190, top: 310, bottom: 470, stroke: 5, maxDeg: 85, outward: false, eye: guildeEye,
    outline: [[130, 470], [130, 340]]
      .concat(quad([130, 340], [130, 310], [190, 310], 8)).concat([[190, 470]]),
    planks: [[150, 340, 190, 340], [150, 400, 190, 400], [150, 450, 190, 450]],
    rings: [{ x: 170, y: 390, r: 7, w: 3 }]
  });
  var guildeD = makeLeaf(guildeParent, {
    hinge: 250, free: 190, top: 310, bottom: 470, stroke: 5, maxDeg: 85, outward: false, eye: guildeEye,
    outline: [[250, 470], [250, 340]]
      .concat(quad([250, 340], [250, 310], [190, 310], 8)).concat([[190, 470]]),
    planks: [[190, 340, 230, 340], [190, 400, 230, 400], [190, 450, 230, 450]],
    rings: [{ x: 210, y: 390, r: 7, w: 3 }]
  });
  doors.push({ group: guildeGroup, leaves: [guildeG, guildeD] });

  // Double porte (tour, guilde) : un battant, l'autre, les deux ensemble ou les deux en
  // decale, chacun ouvert plus ou moins (pas toujours completement).
  function cycleDouble(g, d, pauseKey, pauseDef) {
    var mode = Math.floor(Math.random() * 4);
    var end = 0;
    function go(leaf, delay) { end = Math.max(end, swing(leaf, rand(0.3, 1), delay)); }
    if (mode === 0) go(g, 0);
    else if (mode === 1) go(d, 0);
    else if (mode === 2) { go(g, 0); go(d, rand(0, 300)); }
    else {
      var first = Math.random() < 0.5 ? g : d;
      go(first, 0);
      go(first === g ? d : g, rand(800, 3000));
    }
    setTimeout(function () { cycleDouble(g, d, pauseKey, pauseDef); }, end + cfgMs(pauseKey, pauseDef));
  }
  function cycleTour() { cycleDouble(tourG, tourD, 'portes.tour.pause', [15, 45]); }
  function cycleGuilde() { cycleDouble(guildeG, guildeD, 'portes.guilde.pause', [15, 40]); }

  function cycleAuberge() {
    var end = swing(auberge, rand(0.4, 1), 0);
    setTimeout(cycleAuberge, end + cfgMs('portes.auberge.pause', [18, 50]));
  }

  setTimeout(cycleTour, cfgMs('portes.tour.premiere', [4, 15]));
  setTimeout(cycleAuberge, cfgMs('portes.auberge.premiere', [8, 25]));
  setTimeout(cycleGuilde, cfgMs('portes.guilde.premiere', [6, 20]));
})();

(function () {
  // Fumees de cheminee a intensite variable : un niveau (0..1) derive lentement vers une
  // cible tiree au hasard toutes les 4-14 s (moments calmes, fumee normale, grosses
  // bouffees). Plus le niveau est haut, plus les bouffees sont frequentes, grosses,
  // opaques et montent haut.
  var NS = 'http://www.w3.org/2000/svg';
  function rand(a, b) { return a + Math.random() * (b - a); }

  // Force du vent a l'abscisse x (0..1) : meme rafale que le ble (keyframes wheatGust :
  // calme jusqu'a 55 %, pic a 70 %, retombee 82 %), meme vague qui traverse de gauche a droite.
  var GUSTD = cfg('ble.rafale', 11);
  function gustAt(x) {
    var t = (document.timeline ? document.timeline.currentTime : performance.now()) / 1000;
    var p = (((t - x / 450) % GUSTD) + GUSTD) % GUSTD / GUSTD;
    if (p < 0.55) return 0;
    if (p < 0.70) return (p - 0.55) / 0.15;
    if (p < 0.82) return 1 - 0.625 * (p - 0.70) / 0.12;
    return 0.375 * (1 - (p - 0.82) / 0.18);
  }
  var WIND = cfg('fumee.vent', 1);
  function smoke(id, wind) {
    var g = document.querySelector('#' + id + ' .puffs');
    var gx = document.getElementById(id).getBoundingClientRect().left;
    var level = rand(0.3, 0.6), target = level, nextChange = 0;

    function retarget(now) {
      var r = Math.random();
      var pForte = cfg('fumee.probaForte', 0.2), pCalme = cfg('fumee.probaCalme', 0.3);
      if (r < pForte) target = rand(0.85, 1);                 // grosse bouffee
      else if (r < pForte + pCalme) target = rand(0.05, 0.25); // presque eteint
      else target = rand(0.3, 0.6);                // normal
      nextChange = now + cfgMs('fumee.changement', [4, 14]);
    }

    function puff() {
      var I = level, k = 0.8 + 0.5 * I;
      var e = document.createElementNS(NS, 'ellipse');
      e.setAttribute('class', 'smoke-puff');
      e.setAttribute('cx', rand(-4, 4).toFixed(1));
      e.setAttribute('rx', (rand(9, 13) * k).toFixed(1));
      e.setAttribute('ry', (rand(7, 10) * k).toFixed(1));
      e.setAttribute('fill', Math.random() < 0.5 ? '#3a2a1a' : '#4a3826');
      e.setAttribute('opacity', 0);
      g.appendChild(e);
      // Vent de fond (vers la droite, comme le ble) + rafale : la fumee se couche et monte moins
      var gu = gustAt(gx);
      var dx = WIND * (20 + 110 * gu) + rand(-12, 12) + wind * 0.3, dy = -rand(140, 190) * k * (1 - 0.35 * gu);
      var a = e.animate([
        { transform: 'translate(0px,0px) scale(0.5)', opacity: 0 },
        { opacity: 0.15 + 0.45 * I, offset: 0.12 },
        { transform: 'translate(' + dx.toFixed(1) + 'px,' + dy.toFixed(1) + 'px) scale(' + (1.5 + I).toFixed(2) + ')', opacity: 0 }
      ], { duration: rand(3800, 5200) * (1 + 0.3 * I), easing: 'ease-out' });
      a.onfinish = function () { e.remove(); };
    }

    function step() {
      var now = performance.now();
      if (now > nextChange) retarget(now);
      level += (target - level) * 0.25;
      puff();
      setTimeout(step, (1800 - 1500 * level) * rand(0.8, 1.2) / Math.max(0.1, cfg('fumee.densite', 1)));
    }
    step();
  }

  if (cfg('fumee.actives.forge', true)) smoke('forge-smoke', 0);
  if (cfg('fumee.actives.boulangerie', true)) smoke('boulangerie-smoke', 0);
  if (cfg('fumee.actives.cabane', true)) smoke('cabane-smoke', 0);
  if (cfg('fumee.actives.paysan', true)) smoke('paysan-smoke', 0);
  if (cfg('fumee.actives.hobbit', true)) smoke('hobbit-smoke', 0);
})();

(function () {
  // Cloche de la chapelle : une volee environ toutes les 2 minutes. Balancement amorti
  // autour de l'anse (montee ~1 s, ~4 s de volee, extinction ~3 s), amplitude limitee pour
  // rester dans la baie ; le battant suit avec un retard, ce qui le fait frapper la robe.
  var robe = document.querySelector('#cloche-chapelle .robe');
  var battant = document.querySelector('#cloche-chapelle .battant');
  var A = cfg('cloche.amplitude', 10), T = cfg('cloche.balancement', 1.5) * 1000;
  var DUR = cfg('cloche.duree', 8) * 1000, LAG = 180;
  // Enveloppe : montee 1/8, volee jusqu'a 5/8, extinction sur le reste.
  function env(t) {
    if (t < 0 || t > DUR) return 0;
    if (t < DUR / 8) return t / (DUR / 8);
    if (t < DUR * 5 / 8) return 1;
    return 1 - (t - DUR * 5 / 8) / (DUR * 3 / 8);
  }
  function angle(t) { return A * env(t) * Math.sin(2 * Math.PI * t / T); }
  var start = 0;
  function frame(now) {
    var t = now - start;
    var a = angle(t);
    robe.setAttribute('transform', 'rotate(' + a.toFixed(2) + ' -10 -125)');
    battant.setAttribute('transform', 'rotate(' + (1.6 * (angle(t - LAG) - a)).toFixed(2) + ' -10 -114)');
    if (t < DUR + LAG) requestAnimationFrame(frame);
    else { robe.removeAttribute('transform'); battant.removeAttribute('transform'); }
  }
  function ring() {
    start = performance.now();
    requestAnimationFrame(frame);
    setTimeout(ring, DUR + cfgMs('cloche.intervalle', [105, 135]));
  }
  setTimeout(ring, cfgMs('cloche.premiere', [20, 60]));
})();

(function () {
  // Champs de ble sur les collines (calque 02-hill-bg.svg), herbe, forets et chemin du moulin
  // (calque 02-buildings/02-windmill-bg.svg, porte en (1990,560)). Les epis sont plantes en rangs qui
  // suivent la crete (perspective : rangs et epis de plus en plus espaces/grands vers le
  // bas), avec la teinte de la parcelle dessinee dans le calque ; parcelles labourees et
  // chemin laisses nus. Generation deterministe (PRNG fixe). Chaque segment de rang
  // (~220u) est un seul <path>, anime par wheat-sway / wheat-gust (voir <style>).
  var NS = 'http://www.w3.org/2000/svg';
  var root = document.getElementById('champs-ble');
  var seed = 4242;
  function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
  function r1(v) { return Math.round(v * 10) / 10; }

  // Cretes : memes beziers quadratiques que #colline-pres / #colline-loin du calque.
  var NEAR = [[[-20, 660], [700, 565], [1500, 545]], [[1500, 545], [2100, 535], [2500, 600]],
              [[2500, 600], [2900, 665], [3300, 688]], [[3300, 688], [3600, 700], [3860, 712]]];
  var FAR = [[[-20, 690], [600, 650], [1300, 625]], [[1300, 625], [2100, 600], [2650, 565]],
             [[2650, 565], [3250, 525], [3860, 610]]];
  function crest(segs, x) {
    for (var i = 0; i < segs.length; i++) {
      var a = segs[i][0], c = segs[i][1], b = segs[i][2];
      if (x < a[0] || x > b[0]) continue;
      var lo = 0, hi = 1;
      for (var k = 0; k < 24; k++) {
        var t = (lo + hi) / 2, xt = (1 - t) * (1 - t) * a[0] + 2 * t * (1 - t) * c[0] + t * t * b[0];
        if (xt < x) lo = t; else hi = t;
      }
      return (1 - lo) * (1 - lo) * a[1] + 2 * lo * (1 - lo) * c[1] + lo * lo * b[1];
    }
    return null;
  }

  // Parcelles de la colline proche (limites penchees : x en haut y=500 / en bas y=800).
  var PARCELS = [[-20, -20, 'dark'], [520, 470, 'light'], [1050, 1010, 'earth'], [1450, 1430, 'dark'],
                 [2000, 2010, 'light'], [2550, 2580, 'forest'], [3100, 3150, 'earth'], [3860, 3860, null]];
  function nearKind(x, y) {
    var t = (y - 500) / 300;
    for (var i = 0; i < PARCELS.length - 1; i++) {
      var xr = PARCELS[i + 1][0] + (PARCELS[i + 1][1] - PARCELS[i + 1][0]) * t;
      if (x < xr) return PARCELS[i][2];
    }
    return null;
  }
  function farKind(x) {
    return x < 2680 ? 'light' : x < 3000 ? 'earth' : x < 3420 ? 'forest' : 'light';
  }
  var COLORS = { dark: '#6a5030', light: '#8a6a3a', grass: '#7d6c3c' };

  // Chemin du moulin : ligne centrale [x, y, demi-largeur], du pied du rempart a la porte.
  var PATH = [[2075, 810, 30], [2030, 770, 25], [1955, 738, 19], [1925, 705, 15],
              [1975, 672, 12], [2035, 640, 10], [2025, 606, 8], [1995, 580, 6], [1990, 562, 5]];
  // Echantillonnage lisse (Catmull-Rom) de la ligne centrale.
  var pts = [];
  for (var i = 0; i < PATH.length - 1; i++) {
    var p0 = PATH[Math.max(0, i - 1)], p1 = PATH[i], p2 = PATH[i + 1], p3 = PATH[Math.min(PATH.length - 1, i + 2)];
    for (var s = 0; s < 8; s++) {
      var t = s / 8, t2 = t * t, t3 = t2 * t, q = [];
      for (var k = 0; k < 3; k++)
        q.push(0.5 * (2 * p1[k] + (-p0[k] + p2[k]) * t + (2 * p0[k] - 5 * p1[k] + 4 * p2[k] - p3[k]) * t2 +
                      (-p0[k] + 3 * p1[k] - 3 * p2[k] + p3[k]) * t3));
      pts.push(q);
    }
  }
  pts.push(PATH[PATH.length - 1]);
  function onPath(x, y, margin) {
    for (var i = 0; i < pts.length; i++) {
      var dx = x - pts[i][0], dy = y - pts[i][1], r = pts[i][2] + margin;
      if (dx * dx + dy * dy < r * r) return true;
    }
    return false;
  }
  function offsetLine(f) {
    var left = [], right = [];
    for (var i = 0; i < pts.length; i++) {
      var a = pts[Math.max(0, i - 1)], b = pts[Math.min(pts.length - 1, i + 1)];
      var tx = b[0] - a[0], ty = b[1] - a[1], n = Math.sqrt(tx * tx + ty * ty) || 1;
      var nx = -ty / n, ny = tx / n, w = pts[i][2] * f;
      left.push(r1(pts[i][0] + nx * w) + ',' + r1(pts[i][1] + ny * w));
      right.push(r1(pts[i][0] - nx * w) + ',' + r1(pts[i][1] - ny * w));
    }
    return [left, right];
  }
  function el(tag, attrs, parent) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    parent.appendChild(e);
    return e;
  }
  var chemin = root.querySelector('.chemin');
  var edge = offsetLine(1);
  el('path', { d: 'M ' + edge[0].join(' L ') + ' L ' + edge[1].reverse().join(' L ') + ' Z',
               fill: '#b08a56', stroke: '#5a4028', 'stroke-width': 1.8, 'stroke-linejoin': 'round',
               filter: 'url(#sketchyMedium)' }, chemin);
  var ruts = offsetLine(0.4);
  el('path', { d: 'M ' + ruts[0].join(' L ') + ' M ' + ruts[1].join(' L '), fill: 'none',
               stroke: '#7a5a32', 'stroke-width': 1.3, opacity: 0.7 }, chemin);

  // Epi au pied (x,y), hauteur ~30*s, legere inclinaison l.
  function ear(x, y, s, l) {
    function px(h) { return r1(x + l * h / 30); }
    var d = 'M' + r1(x) + ',' + r1(y) + 'Q' + r1(x + 1.5 * s) + ',' + r1(y - 14 * s) + ' ' + px(30 * s) + ',' + r1(y - 30 * s);
    [26, 21, 16].forEach(function (h) {
      var cx = px(h * s), cy = y - h * s;
      d += 'M' + r1(cx - 4 * s) + ',' + r1(cy) + 'L' + r1(cx) + ',' + r1(cy - 3 * s) + 'L' + r1(cx + 4 * s) + ',' + r1(cy);
    });
    var tx = px(26 * s), ty = y - 26 * s;
    d += 'M' + r1(tx - 4 * s) + ',' + r1(ty) + 'L' + r1(tx - 7 * s) + ',' + r1(ty - 7 * s) +
         'M' + r1(tx + 4 * s) + ',' + r1(ty) + 'L' + r1(tx + 7 * s) + ',' + r1(ty - 7 * s);
    return d;
  }

  // Rangs -> segments {cle: {d, x, s, kind}}
  var X0 = 1300, X1 = 3860, CHUNK = 220, segs = {};
  function plant(key, kind, x, y, s) {
    var g = segs[key] || (segs[key] = { d: '', x: x, s: s, kind: kind });
    if (kind === 'grass') g.d += tuft(x + (rnd() - 0.5) * 4, y + (rnd() - 0.5) * 2, s * (0.8 + rnd() * 0.4));
    else g.d += ear(x + (rnd() - 0.5) * 3, y + (rnd() - 0.5) * 2, s * (0.85 + rnd() * 0.3), (rnd() - 0.3) * 4 * s);
  }
  // Touffe d'herbe au pied (x,y), hauteur ~11*s : trois brins.
  function tuft(x, y, s) {
    var b = r1(x) + ',' + r1(y);
    return 'M' + b + 'Q' + r1(x - 2 * s) + ',' + r1(y - 5 * s) + ' ' + r1(x - 4.5 * s) + ',' + r1(y - 9 * s) +
           'M' + b + 'L' + r1(x + 0.8 * s) + ',' + r1(y - 11 * s) +
           'M' + b + 'Q' + r1(x + 2 * s) + ',' + r1(y - 5 * s) + ' ' + r1(x + 4.5 * s) + ',' + r1(y - 8 * s);
  }
  // Clairiere de la cabane du bucheron (calque 02-buildings/02-cabin-bg.svg) : ni arbre ni herbe
  // devant elle (les arbres plus loin, pieds au-dessus de y0, restent derriere elle).
  var CLAIRIERE = [2640, 2755, 630, 812];
  function inClearing(x, y) { return x > CLAIRIERE[0] && x < CLAIRIERE[1] && y > CLAIRIERE[2] && y < CLAIRIERE[3]; }

  // Colline lointaine : pas de ble ; herbe hors de la foret.
  for (var d = 4, row = 0; d < 120; d += 5 + 0.05 * d, row++) {
    for (var x = X0; x < X1; x += 8 + rnd() * 5) {
      var cf = crest(FAR, x), cn = crest(NEAR, x);
      if (cf === null || cn === null) continue;
      var y = cf + d;
      if (y > cn + 2 || farKind(x) === 'forest') continue;
      plant('f' + row + '_' + Math.floor(x / CHUNK), 'grass', x, y, 0.4 + 0.005 * d);
    }
  }
  // Colline proche : de la crete jusque sous le rempart (y=805).
  for (var d2 = 5, row2 = 0; d2 < 280; d2 += 6 + 0.07 * d2, row2++) {
    for (var x2 = X0; x2 < X1; x2 += 7 + 0.05 * d2 + rnd() * 3) {
      var c2 = crest(NEAR, x2);
      if (c2 === null) continue;
      var y2 = c2 + d2;
      if (y2 > 805) continue;
      var kind2 = nearKind(x2, y2);
      if (!kind2 || kind2 === 'forest' || onPath(x2, y2, 4)) continue;
      // Parcelles sans ble (anciennes jacheres) : herbe.
      if (kind2 === 'earth') kind2 = 'grass';
      if (kind2 === 'grass' && inClearing(x2, y2)) continue;
      plant('n' + row2 + '_' + Math.floor(x2 / CHUNK) + kind2, kind2, x2, y2, (kind2 === 'grass' ? 0.6 : 0.38) + 0.0032 * d2);
    }
  }

  // Un <path> par segment, dans deux groupes animes (rafale > balancement). Delais negatifs
  // croissants avec x : la vague traverse le champ de gauche a droite.
  var epis = root.querySelector('.epis');
  var GUST = cfg('ble.rafale', 11), SWAY = cfg('ble.balancement', 3.4);
  Object.keys(segs).forEach(function (k) {
    var g = segs[k];
    var gust = el('g', { 'class': 'wheat-gust' }, epis);
    gust.style.animationDelay = (-(GUST - (g.x / 450) % GUST)).toFixed(2) + 's';   // phase = t - x/450
    var sway = el('g', { 'class': 'wheat-sway' }, gust);
    sway.style.animationDelay = (-(SWAY - (g.x / 900) % SWAY) + (rnd() - 0.5) * 0.4).toFixed(2) + 's';
    el('path', { d: g.d, stroke: COLORS[g.kind], 'stroke-width': r1(0.9 + 0.5 * g.s) }, sway);
  });

  // Forets : parcelles 'forest' (colline proche x~2550-3150, colline lointaine x~3000-3420).
  // Feuillus (houppier en 3 boules) et conifères (2 etages), plantes en rangs comme le ble,
  // tries par y pour que les arbres proches passent devant.
  var trees = [];
  // Lisiere : de moins en moins d'arbres a moins de 'w' unites du bord de la parcelle.
  function edgeKeep(dist, w) { return rnd() < Math.min(1, 0.15 + dist / w); }
  for (var fd = 6; fd < 120; fd += 17) {
    for (var fx = X0; fx < X1; fx += 33 + rnd() * 16) {
      var fcf = crest(FAR, fx), fcn = crest(NEAR, fx);
      if (fcf === null || fcn === null || farKind(fx) !== 'forest') continue;
      var fy = fcf + fd;
      if (fy > fcn + 4 || !edgeKeep(Math.min(fx - 3000, 3420 - fx), 140)) continue;
      trees.push([fx, fy, 1.0 + 0.01 * fd]);
    }
  }
  for (var nd = 10; nd < 280; nd += 25 + 0.18 * nd) {
    for (var nx = X0; nx < X1; nx += 42 + 0.25 * nd + rnd() * 18) {
      var ncn = crest(NEAR, nx);
      if (ncn === null) continue;
      var ny = ncn + nd;
      if (ny > 812 || nearKind(nx, ny) !== 'forest' || inClearing(nx, ny)) continue;
      var nt = (ny - 500) / 300, nl0 = 2550 + 30 * nt, nr0 = 3100 + 50 * nt;
      if (!edgeKeep(Math.min(nx - nl0, nr0 - nx), 110)) continue;
      trees.push([nx, ny, 1.4 + 0.009 * nd]);
    }
  }
  var FILLS = ['#6e5a34', '#7d6a3e', '#5e4c2c', '#857246'];
  function circle(cx, cy, r) {
    return 'M' + r1(cx - r) + ',' + r1(cy) + 'a' + r1(r) + ',' + r1(r) + ' 0 1,0 ' + r1(2 * r) + ',0' +
           'a' + r1(r) + ',' + r1(r) + ' 0 1,0 ' + r1(-2 * r) + ',0';
  }
  var foret = root.querySelector('.foret');
  trees.sort(function (a, b) { return a[1] - b[1]; }).forEach(function (t) {
    var x = t[0] + (rnd() - 0.5) * 4, y = t[1] + (rnd() - 0.5) * 3, s = t[2] * (0.85 + rnd() * 0.35);
    var fill = FILLS[Math.floor(rnd() * FILLS.length)], sw = r1(0.8 + 0.6 * s);
    // Vent : meme phase que le ble a cette abscisse (la vague traverse aussi la foret)
    var tg = el('g', { 'class': 'tree-gust' }, foret);
    tg.style.animationDelay = (-(GUST - (x / 450) % GUST)).toFixed(2) + 's';
    var tree = el('g', { 'class': 'tree-sway' }, tg);
    tree.style.animationDelay = (-(SWAY - (x / 900) % SWAY) + (rnd() - 0.5) * 0.6).toFixed(2) + 's';
    el('path', { d: 'M' + r1(x) + ',' + r1(y) + 'L' + r1(x) + ',' + r1(y - 12 * s), fill: 'none',
                 stroke: '#3a2a14', 'stroke-width': r1(1.2 + 1.5 * s) }, tree);
    if (rnd() < 0.3) {
      // Conifere
      el('path', { d: 'M' + r1(x - 9 * s) + ',' + r1(y - 7 * s) + 'L' + r1(x) + ',' + r1(y - 26 * s) + 'L' + r1(x + 9 * s) + ',' + r1(y - 7 * s) + 'Z' +
                      'M' + r1(x - 7 * s) + ',' + r1(y - 19 * s) + 'L' + r1(x) + ',' + r1(y - 38 * s) + 'L' + r1(x + 7 * s) + ',' + r1(y - 19 * s) + 'Z',
                   fill: fill, 'stroke-width': sw }, tree);
    } else {
      // Feuillu
      el('path', { d: circle(x - 6 * s, y - 16 * s, 8 * s) + circle(x + 6 * s, y - 17 * s, 8 * s) + circle(x, y - 25 * s, 9 * s),
                   fill: fill, 'stroke-width': sw }, tree);
    }
  });
})();

(function () {
  // Puits : de temps en temps, on tourne la manivelle, le seau descend dans le puits
  // (disparait derriere la margelle), reste un instant, puis remonte plein, plus lentement.
  var root = document.getElementById('puits-treuil');
  var corde = root.querySelector('.corde'), seau = root.querySelector('.seau');
  var eau = root.querySelector('.eau'), bras = root.querySelector('.bras'), poignee = root.querySelector('.poignee');
  var gouttes = root.querySelectorAll('.goutte');
  var DOWN = cfg('puits.descente', 3) * 1000, WAIT = 1500, UP = cfg('puits.remontee', 4.5) * 1000;
  var DRAIN = cfg('puits.vidage', 7) * 1000;
  var DEPTH = 85, TURNS_PER_UNIT = 1 / 30, R = 18;  // 1 tour de manivelle par 30u de corde
  function ease(t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; }
  var start = 0, moving = DOWN + WAIT + UP, total = moving + DRAIN;
  function setCrank(angle) {
    var ky = -70 + R * Math.cos(angle);
    bras.setAttribute('y2', ky.toFixed(1));
    poignee.setAttribute('y1', ky.toFixed(1)); poignee.setAttribute('y2', ky.toFixed(1));
    // poignee derriere l'axe (sin<0) : plus fine, comme en retrait
    poignee.setAttribute('stroke-width', Math.sin(angle) < 0 ? 4 : 5.5);
  }
  function frame(now) {
    var t = now - start, off;
    if (t < DOWN) off = DEPTH * ease(t / DOWN);
    else if (t < DOWN + WAIT) off = DEPTH;
    else if (t < moving) off = DEPTH * (1 - ease((t - DOWN - WAIT) / UP));
    else off = 0;
    seau.setAttribute('transform', 'translate(0,' + off.toFixed(1) + ')');
    corde.setAttribute('y2', (56 + off).toFixed(1));
    setCrank(off * TURNS_PER_UNIT * 2 * Math.PI);
    // Eau : pleine a la remontee, puis le seau se vide par en dessous (niveau qui baisse, gouttes)
    var L = t < DOWN ? -1 : t < moving ? 0 : Math.min(1, (t - moving) / DRAIN);
    if (L < 0) { eau.setAttribute('opacity', 0); }
    else {
      eau.setAttribute('cy', (61 + 7 * L).toFixed(1));
      eau.setAttribute('rx', (13 - 3.5 * L).toFixed(1));
      eau.setAttribute('ry', (3.5 - 1.5 * L).toFixed(1));
      eau.setAttribute('opacity', (0.8 * (1 - L * L)).toFixed(2));
    }
    for (var i = 0; i < gouttes.length; i++) {
      if (t < moving || L >= 1) { gouttes[i].setAttribute('opacity', 0); continue; }
      var ph = ((t - moving) / (420 + 160 * i) + i * 0.5) % 1;   // une goutte toutes les ~0.5 s
      gouttes[i].setAttribute('cy', (91 + 14 * ph * ph).toFixed(1));
      gouttes[i].setAttribute('opacity', (0.9 * (1 - ph) * (1 - L)).toFixed(2));
    }
    if (t < total) requestAnimationFrame(frame);
    else { seau.removeAttribute('transform'); corde.setAttribute('y2', 56); setCrank(0); eau.setAttribute('opacity', 0); }
  }
  function cycle() {
    start = performance.now();
    requestAnimationFrame(frame);
    setTimeout(cycle, total + cfgMs('puits.intervalle', [40, 90]));
  }
  setTimeout(cycle, cfgMs('puits.premiere', [10, 30]));
})();

(function () {
  // Vent commun : force du vent (0..1) a l'abscisse x, au meme instant et avec les memes
  // cycles que le ble (rafale 'ble.rafale', balancement 'ble.balancement'), vague qui
  // traverse de gauche a droite. Pilote les fanions et les auvents des tentes.
  var GUSTD = cfg('ble.rafale', 11), SWAYD = cfg('ble.balancement', 3.4);
  var PUISSANCE = cfg('vent.puissance', 1);
  function now() { return (document.timeline ? document.timeline.currentTime : performance.now()) / 1000; }
  function gustAt(x, t) {
    var p = (((t - x / 450) % GUSTD) + GUSTD) % GUSTD / GUSTD;
    if (p < 0.55) return 0;
    if (p < 0.70) return (p - 0.55) / 0.15;
    if (p < 0.82) return 1 - 0.625 * (p - 0.70) / 0.12;
    return 0.375 * (1 - (p - 0.82) / 0.18);
  }
  function windAt(x, t) {
    var sway = 0.5 + 0.5 * Math.sin(2 * Math.PI * (t - x / 900) / SWAYD);
    return Math.min(1, PUISSANCE * (0.25 + 0.15 * sway + 0.6 * gustAt(x, t)));
  }
  function r1(v) { return Math.round(v * 10) / 10; }

  // --- Fanions : angle de chute (pend quand le vent tombe), ondulation plus ample et plus
  // rapide pendant les rafales.
  var flags = Array.prototype.map.call(document.querySelectorAll('#fanions .fanion'), function (e) {
    return { e: e, band: e.nextElementSibling && e.nextElementSibling.classList.contains('fanion-bande') ? e.nextElementSibling : null,
             px: +e.dataset.px, py: +e.dataset.py, hp: +e.dataset.hp, L: +e.dataset.l, h: +e.dataset.h, ph: Math.random() * 6 };
  });
  var N = 16;
  function drawFlag(f, w) {
    var top = f.py - f.hp, a = (1 - w) * 0.85;               // 0 = horizontal, ~50 deg quand calme
    var ca = Math.cos(a), sa = Math.sin(a), amp = (0.2 + 0.6 * w) * f.h;
    var T = [], B = [], M = [];
    for (var i = 0; i <= N; i++) {
      var u = i / N, al = f.L * u * (0.85 + 0.15 * w);
      var off = amp * Math.sin(2 * Math.PI * 1.15 * u - f.ph) * u;
      var bx = f.px + al * ca, by = top + al * sa;
      var hw = f.h * (1 - u * 0.92);
      // perpendiculaire a la direction du fanion
      T.push([bx - sa * off, by + ca * off]);
      B.push([bx - sa * (off + hw), by + ca * (off + hw)]);
      M.push([bx - sa * (off + hw / 2), by + ca * (off + hw / 2)]);
    }
    var d = 'M ' + T.map(function (p) { return r1(p[0]) + ',' + r1(p[1]); }).join(' L ') + ' L ' +
            B.reverse().map(function (p) { return r1(p[0]) + ',' + r1(p[1]); }).join(' L ') + ' Z';
    f.e.setAttribute('d', d);
    if (f.band) f.band.setAttribute('d', 'M ' + M.slice(0, N).map(function (p) { return r1(p[0]) + ',' + r1(p[1]); }).join(' L '));
  }

  // --- Auvents : le bord festonne est souleve et pousse vers la droite selon le vent.
  var awnings = Array.prototype.map.call(document.querySelectorAll('#tentes-auvents .auvent'), function (e) {
    var g = e.dataset.geo.split(',').map(Number);
    var box = e.parentNode.getBoundingClientRect();
    return { e: e, W: g[0], T: g[1], B: g[2], dip: g[3], x: box.left + box.width / 2, ph: Math.random() * 6,
             plis: e.parentNode.querySelector('.auvent-plis') };
  });
  function drawAwning(a, w) {
    var K = cfg('vent.tentes', 0.4);   // les toiles, lourdes et tendues, bougent peu
    var lift = K * (1.5 + 6 * w) * Math.sin(a.ph), dx = K * (2 + 9 * w + (1 + 2 * w) * Math.sin(a.ph + 0.6));
    var puff = -a.T - K * (1 + 4 * w) * Math.sin(a.ph + 1.2), W = a.W, B = a.B;
    var xs = [W + 10, W * 0.5 + 10, W * 0.07 - 10, -W * 0.36 - 10, -W * 0.86, -W - 10];
    var d = 'M ' + (-W) + ',20 Q 0,' + r1(puff) + ' ' + W + ',20 L ' + r1(xs[0] + dx) + ',' + r1(B + lift);
    for (var i = 0; i < 5; i++) {
      var p = xs[i] + dx * (1 - i * 0.12), q = xs[i + 1] + dx * (1 - (i + 1) * 0.12);
      var wv = K * (1 + 3 * w) * Math.sin(a.ph + i * 0.9);
      d += ' Q ' + r1((p + q) / 2) + ',' + r1(B + a.dip + lift + wv) + ' ' + r1(q) + ',' + r1(B + lift + wv * 0.5);
    }
    a.e.setAttribute('d', d + ' Z');
    if (a.plis) a.plis.setAttribute('transform', 'translate(' + r1(dx * 0.5) + ',' + r1(lift * 0.5) + ')');
  }

  var last = performance.now();
  function frame(t) {
    var dt = Math.min(0.1, (t - last) / 1000); last = t;
    var tn = now();
    flags.forEach(function (f) { var w = windAt(f.px, tn); f.ph += dt * 2 * Math.PI * (0.5 + 1.3 * w); drawFlag(f, w); });
    awnings.forEach(function (a) { var w = windAt(a.x, tn); a.ph += dt * 2 * Math.PI * (0.18 + 0.35 * w); drawAwning(a, w); });
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();

(function () {
  // Ciel : nuages et vols d'oiseaux apparaissent au hasard.
  var NS = 'http://www.w3.org/2000/svg';
  function rand(a, b) { return a + Math.random() * (b - a); }
  function el(tag, attrs, parent) { var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); return e; }
  var X0 = 1350, X1 = 3950;   // couloir de vol / de derive (le coin ovale coupe le reste)

  // ---- Nuages : forme festonnee aleatoire, derive vers la droite (sens du vent)
  var nuages = document.getElementById('nuages');
  function cloudPath(w, h) {
    var n = Math.max(3, Math.round(w / rand(45, 70))), d = 'M 0,0';
    for (var i = 0; i < n; i++) {
      var hh = h * (0.45 + 0.55 * Math.sin(Math.PI * (i + 0.5) / n)) * rand(0.75, 1.15);
      d += ' Q ' + (w * (i + 0.5) / n).toFixed(1) + ',' + (-hh * 1.25).toFixed(1) + ' ' + (w * (i + 1) / n).toFixed(1) + ',' + (i === n - 1 ? 0 : -hh * rand(0.2, 0.45)).toFixed(1);
    }
    return d + ' Q ' + (w / 2).toFixed(1) + ',' + (h * rand(0.1, 0.25)).toFixed(1) + ' 0,0 Z';
  }
  var CROSS = cfg('ciel.traverseeNuages', 240);   // secondes pour traverser (moyenne)

  // ---- Nuages speciaux : silhouettes piochees au hasard dans layers/02-nature/clouds/
  // (voir ciel.nuagesSpeciaux dans animations-config.js pour la liste des fichiers).
  var SPECIAUX_FICHIERS = cfg('ciel.nuagesSpeciaux.fichiers', []);
  var SPECIAUX_PROBA = cfg('ciel.nuagesSpeciaux.probabilite', 0.15);
  function spawnSpecialCloud(startFrac) {
    var file = SPECIAUX_FICHIERS[Math.floor(Math.random() * SPECIAUX_FICHIERS.length)];
    var w = rand(160, 300), h = w * 0.66, y = rand(110, 470), sc = rand(0.7, 1.3);
    var g = el('g', {}, nuages);
    var inner = el('g', { transform: 'translate(0,' + y.toFixed(1) + ') scale(' + sc.toFixed(2) + ')' }, g);
    el('image', { href: 'layers/02-nature/clouds/' + file, x: 0, y: (-h).toFixed(1), width: w.toFixed(1), height: h.toFixed(1), opacity: rand(0.85, 1).toFixed(2) }, inner);
    var from = X0 - w * sc - 50, to = X1 + 50, dur = CROSS * rand(0.7, 1.4) * 1000;
    var anim = g.animate([{ transform: 'translateX(' + from + 'px)' }, { transform: 'translateX(' + to + 'px)' }], { duration: dur, easing: 'linear' });
    if (startFrac) anim.currentTime = dur * startFrac;
    anim.onfinish = function () { g.remove(); };
  }

  function spawnCloud(startFrac) {
    if (SPECIAUX_FICHIERS.length && Math.random() < SPECIAUX_PROBA) return spawnSpecialCloud(startFrac);
    var w = rand(160, 480), h = rand(40, 95), y = rand(110, 470), sc = rand(0.55, 1.2);
    var g = el('g', {}, nuages);
    var inner = el('g', { transform: 'translate(0,' + y.toFixed(1) + ') scale(' + sc.toFixed(2) + ')' }, g);
    el('path', { d: cloudPath(w, h), fill: '#efe4c6', stroke: '#6a5030', 'stroke-width': 2.5, 'stroke-linejoin': 'round', opacity: rand(0.8, 0.95).toFixed(2) }, inner);
    el('path', { d: 'M ' + (w * 0.12).toFixed(1) + ',-6 Q ' + (w / 2).toFixed(1) + ',4 ' + (w * 0.88).toFixed(1) + ',-6', fill: 'none', stroke: '#b8a070', 'stroke-width': 5, opacity: 0.5, 'stroke-linecap': 'round' }, inner);
    var from = X0 - w * sc - 50, to = X1 + 50, dur = CROSS * rand(0.7, 1.4) * 1000;
    var anim = g.animate([{ transform: 'translateX(' + from + 'px)' }, { transform: 'translateX(' + to + 'px)' }], { duration: dur, easing: 'linear' });
    if (startFrac) anim.currentTime = dur * startFrac;   // nuages deja en place au demarrage
    anim.onfinish = function () { g.remove(); };
  }
  var nInit = Math.round(rand(3, 6));
  for (var i = 0; i < nInit; i++) spawnCloud(rand(0.05, 0.95));
  (function nextCloud() { spawnCloud(0); setTimeout(nextCloud, cfgMs('ciel.nuages', [25, 70])); })();

  // ---- Oiseaux : vol lent, formation lache qui se deforme, aile lointaine plus petite
  var root = document.getElementById('oiseaux');
  function flock() {
    var n = Math.floor(rand(3, 8)), dir = Math.random() < 0.7 ? 1 : -1;
    var yBase = rand(120, 430), speed = rand(40, 75) * dir, birds = [];
    var x0 = dir > 0 ? X0 - 80 : X1 + 80;
    for (var i = 0; i < n; i++) {
      var s0 = rand(5, 12), e = el('path', { 'stroke-width': (s0 / 5).toFixed(1) }, root);
      birds.push({
        e: e, s: s0,
        dx: -dir * (i * rand(14, 34)) + rand(-12, 12),      // ecart variable, pas de V parfait
        dy: rand(-45, 45),                                  // altitude propre a chaque oiseau
        v: speed * rand(0.9, 1.1),                          // vitesses legerement differentes
        far: rand(0.45, 0.75),                              // aile lointaine plus petite
        curve: rand(0.15, 0.4), ph: rand(0, 6), f: rand(3, 5), bob: rand(5, 16), bobF: rand(0.25, 0.6), glide: rand(0, 10)
      });
    }
    var start = performance.now(), life = ((X1 - X0 + 400) / Math.abs(speed)) * 1000;
    function frame(now) {
      var t = (now - start) / 1000;
      birds.forEach(function (b) {
        // plane de temps en temps (ailes immobiles, legerement relevees)
        var gliding = Math.sin(t * 0.35 + b.glide) > 0.75;
        var flap = gliding ? 0.25 : Math.sin(b.ph + t * b.f);
        var x = x0 + b.dx + b.v * t, y = yBase + b.dy + b.bob * Math.sin(t * b.bobF + b.ph) + 6 * Math.sin(t * 0.17 + b.glide);
        var wy = -b.s * (0.15 + 0.55 * flap), near = b.s, farW = b.s * b.far;
        // aile proche (dans le sens de vol) plus grande, aile lointaine plus petite et plus courte
        var nx = dir, fx = -dir;
        b.e.setAttribute('d',
          'M ' + (x + fx * farW).toFixed(1) + ',' + (y + wy * b.far).toFixed(1) +
          ' Q ' + (x + fx * farW * 0.4).toFixed(1) + ',' + (y + wy * 0.2 * b.far - farW * b.curve).toFixed(1) + ' ' + x.toFixed(1) + ',' + y.toFixed(1) +
          ' Q ' + (x + nx * near * 0.4).toFixed(1) + ',' + (y + wy * 0.2 - near * b.curve).toFixed(1) + ' ' + (x + nx * near).toFixed(1) + ',' + (y + wy).toFixed(1));
      });
      if (t * 1000 < life) requestAnimationFrame(frame);
      else birds.forEach(function (b) { b.e.remove(); });
    }
    requestAnimationFrame(frame);
    setTimeout(flock, cfgMs('ciel.oiseaux', [20, 60]));   // un vol peut en croiser un autre
  }
  setTimeout(flock, cfgMs('ciel.premierVol', [3, 10]));
})();

(function () {
  // Jour et nuit : suit la meme horloge virtuelle que les aiguilles de la tour
  // (mode 'reel' ou 'accelere', voir heureVirtuelle ci-dessus).
  //
  // Heures de lever/coucher du soleil en France (heure legale civile, changements
  // d'heure ete/hiver inclus) par mois, valeurs moyennes approchees pour la France
  // metropolitaine. Utilisees quand jourNuit.lever / jourNuit.coucher ne sont pas
  // fixes explicitement dans la config (valeur null = automatique selon le mois en cours).
  var SOLEIL_FRANCE = [
    [8.6, 17.4], [7.9, 18.3], [7.2, 19.1], [7.0, 20.6], [6.2, 21.3], [5.8, 21.9],
    [6.0, 21.8], [6.7, 21.1], [7.4, 20.1], [8.0, 19.0], [7.7, 17.2], [8.4, 16.9]
  ];
  var soleilMois = SOLEIL_FRANCE[new Date().getMonth()];
  var leverCfg = cfg('jourNuit.lever', null), coucherCfg = cfg('jourNuit.coucher', null);
  var LEVER = leverCfg === null ? soleilMois[0] : leverCfg;
  var COUCHER = coucherCfg === null ? soleilMois[1] : coucherCfg;
  var NUIT = cfg('jourNuit.obscurite', 0.6);
  var soleil = document.getElementById('soleil'), lune = document.getElementById('lune');
  var etoiles = document.getElementById('etoiles');
  var voile = document.getElementById('voile-nuit'), crep = document.getElementById('voile-crepuscule');
  var lueur = document.getElementById('lueur-astre'), vign = document.getElementById('vignette-nuit');
  var AMB = cfg('jourNuit.lumiereAmbiante', 1);
  function smooth(a, b, x) { var t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); }
  // Position sur l'arc du ciel (p : 0 lever -> 1 coucher), cache par les collines aux extremites
  function arc(p) { return [1650 + p * 2100, 640 - 470 * Math.sin(Math.PI * p)]; }
  function update() {
    var h = heureVirtuelle(), dayLen = COUCHER - LEVER;
    var pd = (h - LEVER) / dayLen;                                   // soleil
    var pn = ((h - COUCHER + 24) % 24) / (24 - dayLen);              // lune
    var sunUp = pd > -0.05 && pd < 1.05, moonUp = pn > -0.05 && pn < 1.05;
    if (sunUp) { var a = arc(pd); soleil.setAttribute('transform', 'translate(' + a[0].toFixed(1) + ',' + a[1].toFixed(1) + ')'); }
    if (moonUp) { var m = arc(pn); lune.setAttribute('transform', 'translate(' + m[0].toFixed(1) + ',' + m[1].toFixed(1) + ')'); }
    soleil.setAttribute('opacity', sunUp ? 1 : 0);
    lune.setAttribute('opacity', moonUp ? 1 : 0);
    // obscurite : 0 le jour, 1 la nuit, transitions d'environ 1 h autour du lever et du coucher
    var dark = 1 - smooth(LEVER - 0.5, LEVER + 0.75, h) * (1 - smooth(COUCHER - 0.75, COUCHER + 0.5, h));
    // teinte chaude : pic au lever et au coucher
    var warm = Math.max(Math.exp(-Math.pow((h - LEVER) / 0.7, 2)), Math.exp(-Math.pow((h - COUCHER) / 0.7, 2)));
    voile.setAttribute('opacity', (dark * NUIT).toFixed(3));
    crep.setAttribute('opacity', (warm * 0.22).toFixed(3));
    // Lueur ambiante : centree sur le soleil le jour, sur la lune la nuit ; plus forte quand
    // l'astre est haut, chaude et rasante au lever/coucher.
    var src = null, amb = 0;
    if (sunUp && dark < 0.6) { src = arc(pd); amb = (1 - dark) * (0.55 + 0.45 * Math.sin(Math.PI * Math.min(1, Math.max(0, pd)))); lueur.setAttribute('fill', 'url(#lueur-soleil)'); }
    else if (moonUp) { src = arc(pn); amb = dark * 0.25 * Math.sin(Math.PI * Math.min(1, Math.max(0, pn))); lueur.setAttribute('fill', 'url(#lueur-lune)'); }
    if (src) { lueur.setAttribute('cx', src[0].toFixed(1)); lueur.setAttribute('cy', src[1].toFixed(1)); }
    lueur.setAttribute('opacity', (AMB * amb).toFixed(3));
    vign.setAttribute('opacity', (dark * 0.7).toFixed(3));
    etoiles.setAttribute('opacity', Math.max(0, (dark - 0.4) / 0.6).toFixed(2));
    document.documentElement.classList.toggle('nuit', dark > 0.5);
  }
  update();
  setInterval(update, tempsMode === 'accelere' ? 100 : 5000);
})();
});
